function dump(n, depth) {
  if (!n) return null;
  const o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.type === "TEXT") { o.chars = n.characters; o.font = n.fontName; o.size = n.fontSize; o.fills = n.fills; }
  if ("cornerRadius" in n) o.radius = n.cornerRadius;
  if ("fills" in n && n.type !== "TEXT") o.fills = n.fills;
  if ("strokes" in n) o.strokes = n.strokes;
  if ("layoutMode" in n && n.layoutMode !== "NONE") { o.layout = n.layoutMode; o.gap = n.itemSpacing; o.pad = [n.paddingLeft,n.paddingRight,n.paddingTop,n.paddingBottom]; o.primary = n.primaryAxisSizingMode; o.counter = n.counterAxisSizingMode; }
  if (depth > 0 && "children" in n) o.children = n.children.map(c => dump(c, depth-1));
  return o;
}
