const rows=[
 {name:"Pomelo One 14 Pro Max 128GB Deep Purple",code:"#25139526913984",price:"$1399",img:"Photo_Phone_Purple"},
 {name:"Pomelo Pods Max Silver",code:"#53459358345",price:"$549",img:"Photo_Headphones_Silver"},
 {name:"Pomelo Watch Series 9 GPS 41mm Starlight Aluminium",code:"#63632324",price:"$399",img:"Photo_Watch_Starlight"}
];
for(const r of rows){
 const ri=CARTROW.createInstance();
 left.appendChild(ri);ri.layoutSizingHorizontal="FILL";
 const nameNode=ri.findOne(n=>n.type==="TEXT"&&n.name==="Name");
