 const priceNode=ri.findOne(n=>n.type==="TEXT"&&n.name==="Price");
 nameNode.characters=r.name;codeNode.characters=r.code;priceNode.characters=r.price;
 const photoInst=ri.findOne(n=>n.type==="INSTANCE"&&n.name==="Photo");
 if(photoInst&&photo(r.img))photoInst.swapComponent(photo(r.img));
}

