function T(chars,size,style,color){const t=figma.createText();t.fontName={family:"Inter",style:style||"Regular"};t.fontSize=size;t.characters=chars;t.fills=[{type:"SOLID",color:color||C.ink}];return t;}
function F(name,dir,gap,pad){const f=figma.createFrame();f.name=name;f.layoutMode=dir;f.itemSpacing=gap||0;if(pad){f.paddingLeft=pad[0];f.paddingRight=pad[1];f.paddingTop=pad[2];f.paddingBottom=pad[3];}f.fills=[];return f;}

