function dump(n,d,max){let s=" ".repeat(d)+n.type+" "+n.name+(n.type==="TEXT"?' "'+n.characters.slice(0,25)+'"':"")+" ["+Math.round(n.width)+"x"+Math.round(n.height)+"]\n";if("children" in n&&d<max){for(const c of n.children)s+=dump(c,d+1,max);}return s;}
